-- Asset Transformation Engine v1 domain schema. PostgreSQL / Supabase compatible.
create extension if not exists pgcrypto;
create type gate_status as enum ('NOT_EVALUATED','PASS','HOLD','FAIL');
create type confidence_grade as enum ('A','B','C','D','X');
create type opportunity_stage as enum ('transformation_hypothesis','gated_opportunity','asset_opportunity','lead_candidate','archived','killed');
create type recommendation as enum ('kill','hold','watch','investigate','advance','partner','build');

create table therapeutic_areas (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null default '', created_at timestamptz not null default now());
create table indications (id uuid primary key default gen_random_uuid(), therapeutic_area_id uuid not null references therapeutic_areas, name text not null, slug text not null unique, ontology_id text, description text not null default '', created_at timestamptz not null default now());
create table targets (id uuid primary key default gen_random_uuid(), symbol text not null unique, name text not null, target_type text not null, uniprot_id text, ensembl_id text, description text not null default '', metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table mechanisms (id uuid primary key default gen_random_uuid(), name text not null, description text not null default '', mechanism_type text not null, created_at timestamptz not null default now());
create table mechanism_targets (mechanism_id uuid references mechanisms on delete cascade, target_id uuid references targets on delete cascade, role text not null check(role in ('primary','secondary','required_partner')), primary key(mechanism_id,target_id,role));
create table mechanism_contexts (id uuid primary key default gen_random_uuid(), mechanism_id uuid not null references mechanisms, indication_id uuid not null references indications, context_description text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(mechanism_id,indication_id));
create table assets (id uuid primary key default gen_random_uuid(), name text not null, generic_name text, development_code text, asset_type text not null, modality text not null, company_name text, development_status text, highest_phase text, approval_status text, description text not null default '', metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table asset_mechanisms (asset_id uuid references assets on delete cascade, mechanism_id uuid references mechanisms on delete cascade, relationship text not null, primary key(asset_id,mechanism_id));
create table mechanism_context_reference_assets (mechanism_context_id uuid references mechanism_contexts on delete cascade, asset_id uuid references assets on delete cascade, role text not null check(role in ('validation','standard_of_care','failed_asset','historical')), notes text, primary key(mechanism_context_id,asset_id,role));
create table constraint_types (id uuid primary key default gen_random_uuid(), parent_id uuid references constraint_types, code text not null unique, name text not null, description text not null default '', sort_order integer not null default 0);
create table constraints (id uuid primary key default gen_random_uuid(), mechanism_context_id uuid not null references mechanism_contexts, constraint_type_id uuid not null references constraint_types, name text not null, statement text not null, clinical_manifestation text not null, causal_mechanism text not null, status text not null check(status in ('candidate','validated','archived','killed')), alternative_explanations jsonb not null default '[]', evidence_gaps jsonb not null default '[]', created_by_type text not null, created_by_user_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table constraint_reference_assets (constraint_id uuid references constraints on delete cascade, asset_id uuid references assets on delete cascade, role text not null, notes text, primary key(constraint_id,asset_id,role));
create table drug_properties (id uuid primary key default gen_random_uuid(), category text not null, code text not null unique, name text not null, description text not null default '');
create table clinical_advantages (id uuid primary key default gen_random_uuid(), code text not null unique, category text not null, name text not null, description text not null default '', check(code <> 'better_drug'));
create table transformations (id uuid primary key default gen_random_uuid(), family text not null, name text not null, engineering_primitive text not null, description text not null default '', technical_requirements jsonb not null default '[]', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table transformation_drug_properties (transformation_id uuid references transformations on delete cascade, drug_property_id uuid references drug_properties on delete cascade, effect_type text not null, rationale text not null, primary key(transformation_id,drug_property_id));
create table transformation_constraint_types (transformation_id uuid references transformations on delete cascade, constraint_type_id uuid references constraint_types on delete cascade, fit_class text not null check(fit_class in ('strong_match','plausible_match','weak_match','generally_inappropriate')), notes text, primary key(transformation_id,constraint_type_id));
create table sources (id uuid primary key default gen_random_uuid(), source_type text not null, title text not null, publisher text, authors jsonb not null default '[]', url text, doi text, pmid text, clinical_trial_id text, patent_id text, regulatory_document_id text, publication_date date, metadata jsonb not null default '{}', retrieved_at timestamptz not null default now(), created_at timestamptz not null default now());
create table evidence_claims (id uuid primary key default gen_random_uuid(), source_id uuid not null references sources, claim_text text not null, claim_type text not null, species text, evidence_level integer not null check(evidence_level between 1 and 5), directness text not null, independent_replication boolean, source_locator text, source_excerpt text, extraction_confidence confidence_grade not null, extracted_by text not null, extraction_model text, human_verified boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table observations (id uuid primary key default gen_random_uuid(), statement text not null, observation_type text not null, mechanism_context_id uuid references mechanism_contexts, asset_id uuid references assets, confidence confidence_grade not null, created_by_type text not null, created_by_user_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table observation_evidence (observation_id uuid references observations on delete cascade, evidence_claim_id uuid references evidence_claims on delete cascade, relationship text not null check(relationship in ('supports','contradicts','context')), weight numeric, primary key(observation_id,evidence_claim_id));
create table constraint_observations (constraint_id uuid references constraints on delete cascade, observation_id uuid references observations on delete cascade, relationship text not null, primary key(constraint_id,observation_id));
create table opportunity_families (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, transformation_id uuid references transformations, shared_constraint_description text not null, family_thesis text, family_thesis_complete boolean not null default false, stage text not null, recommendation recommendation not null, independent_target_count integer not null default 0, tier_1_count integer not null default 0, tier_2_count integer not null default 0, current_company_formation_score numeric, current_confidence confidence_grade, why_now text, why_not_already text, why_this_company text, what_compounds text, strongest_argument text, strongest_objection text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table opportunities (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, mechanism_context_id uuid not null references mechanism_contexts, constraint_id uuid not null references constraints, transformation_id uuid not null references transformations, primary_drug_property_id uuid not null references drug_properties, stage opportunity_stage not null, recommendation recommendation not null, mandatory_thesis text, mandatory_thesis_complete boolean not null default false, overall_gate_status gate_status not null default 'NOT_EVALUATED', current_score numeric check(current_score between 0 and 100), current_confidence confidence_grade, sensitivity_low numeric, sensitivity_high numeric, opportunity_family_id uuid references opportunity_families, strongest_supporting_argument text, strongest_disconfirming_argument text, why_might_we_be_wrong text, created_by_type text not null, created_by_user_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), last_reviewed_at timestamptz, version integer not null default 1, check(overall_gate_status='PASS' or current_score is null));
create table opportunity_clinical_advantages (opportunity_id uuid references opportunities on delete cascade, clinical_advantage_id uuid references clinical_advantages, is_primary boolean not null default false, rationale text not null, primary key(opportunity_id,clinical_advantage_id));
create unique index one_primary_advantage on opportunity_clinical_advantages(opportunity_id) where is_primary;
create table opportunity_reference_assets (opportunity_id uuid references opportunities on delete cascade, asset_id uuid references assets, role text not null, notes text, primary key(opportunity_id,asset_id,role));
create table opportunity_architecture_components (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references opportunities on delete cascade, component_type text not null, name text not null, reference_asset_id uuid references assets, target_id uuid references targets, component_class text, description text, metadata jsonb not null default '{}', sort_order integer not null default 0);
create table killer_assumptions (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references opportunities on delete cascade, statement text not null, category text not null, criticality text not null check(criticality in ('fatal','major','moderate')), confidence confidence_grade not null, status text not null check(status in ('untested','partially_supported','supported','refuted')), falsification_consequence text not null, best_test text not null, next_best_evidence text, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table assumption_evidence (assumption_id uuid references killer_assumptions on delete cascade, evidence_claim_id uuid references evidence_claims, relationship text not null, primary key(assumption_id,evidence_claim_id));
create table diligence_actions (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references opportunities on delete cascade, assumption_id uuid references killer_assumptions, question text not null, action_type text not null, priority integer not null, expected_information_gain text not null, status text not null, result_summary text, created_at timestamptz not null default now(), completed_at timestamptz);
create table scoring_frameworks (id uuid primary key default gen_random_uuid(), name text not null, version text not null, description text not null, status text not null, created_at timestamptz not null default now(), unique(name,version));
create table scoring_criteria (id uuid primary key default gen_random_uuid(), framework_id uuid not null references scoring_frameworks, entity_type text not null, code text not null, name text not null, description text not null, is_gate boolean not null, weight numeric not null check(weight>=0 and weight<=1), gate_threshold integer check(gate_threshold between 0 and 5), minimum_confidence confidence_grade, sort_order integer not null, unique(framework_id,entity_type,code));
create table scoring_criterion_levels (criterion_id uuid references scoring_criteria on delete cascade, score integer check(score between 0 and 5), definition text not null, positive_indicators jsonb not null default '[]', negative_indicators jsonb not null default '[]', primary key(criterion_id,score));
create table ai_analysis_runs (id uuid primary key default gen_random_uuid(), analysis_type text not null, model_name text not null, model_version text, prompt_template_version text not null, input_hash text not null, input_payload jsonb not null, output_payload jsonb not null, status text not null, created_at timestamptz not null default now(), completed_at timestamptz, accepted_by_user_id uuid, accepted_at timestamptz);
create table assessments (id uuid primary key default gen_random_uuid(), criterion_id uuid not null references scoring_criteria, mechanism_context_id uuid references mechanism_contexts, constraint_id uuid references constraints, opportunity_id uuid references opportunities, opportunity_family_id uuid references opportunity_families, score integer not null check(score between 0 and 5), confidence confidence_grade not null, gate_status gate_status, rationale text not null, assessor_type text not null, assessor_user_id uuid, model_name text, analysis_run_id uuid references ai_analysis_runs, framework_id uuid not null references scoring_frameworks, created_at timestamptz not null default now(), supersedes_assessment_id uuid references assessments, check(num_nonnulls(mechanism_context_id,constraint_id,opportunity_id,opportunity_family_id)=1));
create table opportunity_score_snapshots (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references opportunities, framework_id uuid not null references scoring_frameworks, overall_score numeric not null, confidence confidence_grade not null, sensitivity_low numeric, sensitivity_high numeric, components jsonb not null, assessment_ids uuid[] not null, created_at timestamptz not null default now());
create table opportunity_stage_transitions (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references opportunities, from_stage opportunity_stage, to_stage opportunity_stage not null, reason text not null, triggered_by_type text not null, triggered_by_user_id uuid, created_at timestamptz not null default now());
create table opportunity_family_members (family_id uuid references opportunity_families on delete cascade, opportunity_id uuid references opportunities on delete cascade, tier text not null check(tier in ('tier_1_lead','tier_2_pipeline','tier_3_expansion','tier_4_speculative')), is_designated_lead boolean not null default false, rationale text not null, sort_order integer not null default 0, primary key(family_id,opportunity_id));
create table spincos (id uuid primary key default gen_random_uuid(), family_id uuid not null unique references opportunity_families, name text, working_name text not null, company_thesis text not null, status text not null, recommendation recommendation not null, core_technology text not null, product_strategy text not null, platform_strategy text not null, shared_capabilities jsonb not null default '[]', cmc_strategy text, clinical_strategy text, ip_strategy text, capital_intensity text, why_now text not null, why_not_already text not null, strongest_argument text not null, strongest_objection text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table search_runs (id uuid primary key default gen_random_uuid(), name text, therapeutic_area_ids uuid[] not null default '{}', indication_ids uuid[] not null default '{}', mechanism_type text, minimum_human_validation integer not null default 4, constraint_type_ids uuid[] not null default '{}', causal_mechanism_filter text, transformation_ids uuid[] not null default '{}', drug_property_ids uuid[] not null default '{}', clinical_advantage_ids uuid[] not null default '{}', minimum_therapeutic_delta integer not null default 3, minimum_technical_feasibility integer not null default 3, minimum_independent_targets integer not null default 4, minimum_lead_quality_opportunities integer not null default 2, exclusions jsonb not null default '[]', ranking_criteria jsonb not null default '[]', evidence_standard text not null check(evidence_standard in ('strict','balanced','exploratory')), compiled_prompt text not null, status text not null, created_by_user_id uuid, created_at timestamptz not null default now(), completed_at timestamptz);
create index opportunities_filter_idx on opportunities(stage,overall_gate_status,current_score,transformation_id,opportunity_family_id);
create index constraints_filter_idx on constraints(mechanism_context_id,constraint_type_id,status);
create index source_filter_idx on sources(source_type,publication_date);
create index family_filter_idx on opportunity_families(stage,current_company_formation_score);
